/** One of `toolbarMessages`. */
export type ToolbarMessage = (typeof toolbarMessages)[number];

/** Translations of the toolbar's strings, each by its English text (`toolbarMessages`). */
export type ToolbarMessages = Partial<Readonly<Record<ToolbarMessage, string>>>;

/** A message in the reader's language, its `{name}`s filled in. @internal */
export type Translate = (
  message: ToolbarMessage,
  values?: Record<string, string | number>,
) => string;

/** The toolbar's messages, for the menus and dialogs it renders. @internal */
export const MessagesContext = createContext<ToolbarMessages | undefined>(undefined);

/** `messages` as a function; a string that is not a message (an app's own label) is itself. @internal */
export const translator =
  (messages: ToolbarMessages | undefined): Translate =>
  (message, values) => {
    const text = messages?.[message] ?? message;
    return values
      ? text.replace(/\{(\w+)\}/g, (all, name: string) => String(values[name] ?? all))
      : text;
  };

/** The translator of the toolbar around (English outside one). @internal */
export const useT = (): Translate => translator(useContext(MessagesContext));
